import numpy as np
import math

def priority(item, bins, capacity):
    """Best Fit с ограниченными поправками на полезность остатка (v2).

    Основа — Best Fit по остатку r = bins - item. Поверх него:
      * точное заполнение выбирается первым;
      * почти полное заполнение поощряется;
      * «мёртвая зона» штрафуется, если есть хорошая альтернатива;
      * бонус за остаток, кратный размеру предмета или его половине;
      * бонус за остаток, совпадающий со свободным местом другого контейнера;
      * новый контейнер открывается только если больше некуда положить.
    """
    b = np.asarray(bins, dtype=float)
    n = b.size
    if n == 0:
        return np.zeros(0)
    cap = float(capacity)
    it = float(item)
    eps = 1e-09
    idx = np.arange(n)
    r = b - it
    rn = r / cap
    score = -rn.copy()
    has_new = n > 1 and b[-1] >= cap - eps
    if has_new:
        is_old = idx < n - 1
    else:
        is_old = np.ones(n, dtype=bool)
    exact = np.abs(r) < eps
    score[exact] += 10.0
    frac = it / cap
    tiny = max(1.0, 0.03 * cap)
    near = (r > eps) & (r <= tiny + eps)
    if np.any(near):
        if frac <= 0.5:
            w_near = 0.05
        else:
            w_near = 0.035
        score[near] += w_near * (1.0 - r[near] / tiny) + 0.012
    opened = b[is_old]
    typical = max(tiny + 2.0, 0.75 * it)
    if opened.size > 0:
        med = float(np.median(opened))
        typical = min(typical, max(0.08 * cap, 0.6 * med))
    typical = min(typical, 0.4 * cap)
    typical = max(typical, tiny + 2.0)
    dead = (r > tiny + eps) & (r < typical)
    if np.any(dead):
        good_alt = np.any(is_old & (near | exact | (r >= typical)))
        if good_alt:
            t = np.clip((r[dead] - tiny) / (typical - tiny), 0.0, 1.0)
            if frac <= 0.5:
                w = 0.03 + 0.07 * min(1.0, it / (0.4 * cap))
            else:
                w = 0.03
            score[dead] -= w * np.sin(math.pi * t) ** 0.7
    if frac <= 0.5 and it > eps:
        room = (r >= it - eps) & (r >= typical)
        if np.any(room):
            rr = r[room]
            k = np.floor((rr + eps) / it)
            tail = (rr - k * it) / cap
            score[room] += 0.006 + 0.02 * (1.0 - np.minimum(tail * 8.0, 1.0))
        half = 0.5 * it
        if half >= 1.0:
            room2 = (r >= half - eps) & (r < it - eps) & (r >= typical)
            if np.any(room2):
                tail = (r[room2] - half) / cap
                score[room2] += 0.008 * (1.0 - np.minimum(tail * 8.0, 1.0))
        if frac <= 0.2:
            score += 0.003 * (1.0 - b / cap)
    elif frac > 0.5:
        useful = r >= 0.15 * cap
        score[useful] += 0.003
    if 1 < opened.size <= 400:
        cand = np.where(is_old & (r >= typical))[0]
        if cand.size > 0:
            srt = np.sort(opened)
            rc = r[cand]
            pos = np.searchsorted(srt, rc)
            lo = srt[np.clip(pos - 1, 0, srt.size - 1)]
            hi = srt[np.clip(pos, 0, srt.size - 1)]
            d = np.minimum(np.abs(rc - lo), np.abs(rc - hi))
            match = d <= max(1.0, 0.01 * cap) + eps
            score[cand[match]] += 0.004
    score -= 1e-10 * idx
    if has_new:
        score[-1] = float(np.min(score[:-1])) - 1000.0
    return score

import numpy as np
import math

def priority(item, bins, capacity):
    """Best Fit с ограниченными поправками на полезность остатка (v3).

    Изменения относительно v1:
      * «типичный» размер будущего предмета оценивается по медиане,
        нижнему квартилю и минимуму свободного места в открытых контейнерах;
      * штраф «мёртвой зоны» учитывает, насколько хороша альтернатива;
      * мёртвая зона слабо штрафуется и для крупных предметов;
      * бонус за кратность остатка ограничен двумя-тремя копиями предмета;
      * бонус за совпадение остатка со свободным местом другого контейнера
        (как в v0);
      * мелкие предметы тянутся к более заполненным контейнерам.
    Поправки не превышают ~0.1 ёмкости, поэтому меняют порядок Best Fit
    только между кандидатами с близкими остатками.
    """
    b = np.asarray(bins, dtype=float)
    n = b.size
    if n == 0:
        return np.zeros(0)
    cap = float(capacity)
    it = float(item)
    eps = 1e-09
    idx = np.arange(n)
    r = b - it
    score = -(r / cap)
    has_new = n > 1 and b[-1] >= cap - eps
    is_old = idx < n - 1 if has_new else np.ones(n, dtype=bool)
    if n == 1 and b[0] >= cap - eps:
        is_old = np.zeros(n, dtype=bool)
    exact = np.abs(r) < eps
    score[exact] += 10.0
    frac = it / cap
    tiny = max(1.0, 0.03 * cap)
    near = (r > eps) & (r <= tiny + eps)
    if np.any(near):
        w_near = 0.05 if frac <= 0.5 else 0.028
        score[near] += w_near * (1.0 - r[near] / tiny) ** 1.2 + 0.012
    opened = b[is_old]
    if frac <= 0.5:
        typical = max(tiny + 2.0, 0.75 * it)
    else:
        typical = max(tiny + 2.0, 0.12 * cap)
    if opened.size > 0:
        med = float(np.median(opened))
        if opened.size >= 4:
            q25 = float(np.percentile(opened, 25))
        else:
            q25 = med
        est = max(0.08 * cap, 0.45 * med + 0.2 * q25)
        typical = min(typical, est)
    typical = min(typical, 0.4 * cap)
    typical = max(typical, tiny + 2.0)
    good_alt_mask = is_old & (near | exact | (r >= typical))
    good_alt = bool(np.any(good_alt_mask))
    best_alt_quality = 0.0
    if good_alt:
        if np.any(is_old & (near | exact)):
            best_alt_quality = 1.0
        else:
            best_alt_quality = 0.7
    dead = (r > tiny + eps) & (r < typical)
    if np.any(dead):
        t = np.clip((r[dead] - tiny) / (typical - tiny), 0.0, 1.0)
        if good_alt:
            if frac <= 0.5:
                w = 0.03 + 0.075 * min(1.0, it / (0.4 * cap))
            else:
                w = 0.022
            w *= 0.85 + 0.15 * best_alt_quality
            score[dead] -= w * np.sin(math.pi * t) ** 0.7
        elif frac <= 0.5:
            score[dead] += 0.004 * (1.0 - t)
    if frac <= 0.5 and it > eps:
        room = (r >= it - eps) & (r >= typical)
        if np.any(room):
            rr = r[room]
            k = np.floor((rr + eps) / it)
            tail = (rr - k * it) / cap
            good = 1.0 - np.minimum(tail * 8.0, 1.0)
            decay = np.where(k <= 3, 1.0, 0.7)
            bonus = 0.006 + 0.022 * good * decay
            bonus = np.where(tail * cap <= tiny + eps, bonus + 0.004, bonus)
            score[room] += bonus
        half = 0.5 * it
        if half >= 1.0:
            room2 = (r >= half - eps) & (r < it - eps) & (r >= typical)
            if np.any(room2):
                tail = (r[room2] - half) / cap
                score[room2] += 0.008 * (1.0 - np.minimum(tail * 8.0, 1.0))
        if frac <= 0.2:
            score += 0.003 * (1.0 - b / cap)
        elif frac <= 0.4:
            mid = (r > 0.2 * cap) & (r < 0.45 * cap) & is_old
            if np.any(mid):
                score[mid] -= 0.004
    else:
        useful = r >= 0.15 * cap
        score[useful] += 0.002
        if opened.size > 0:
            small_need = max(tiny + 1.0, 0.1 * cap)
            ok = (r >= small_need) & (r < 0.5 * cap) & is_old
            if np.any(ok):
                score[ok] += 0.001
    if 1 < opened.size <= 400:
        cand = np.where(is_old & (r >= typical))[0]
        if cand.size > 0:
            srt = np.sort(opened)
            rc = r[cand]
            pos = np.searchsorted(srt, rc)
            lo = srt[np.clip(pos - 1, 0, srt.size - 1)]
            hi = srt[np.clip(pos, 0, srt.size - 1)]
            d = np.minimum(np.abs(rc - lo), np.abs(rc - hi))
            match = d <= max(1.0, 0.01 * cap) + eps
            score[cand[match]] += 0.003
    score -= 1e-10 * idx
    if has_new:
        score[-1] = float(np.min(score[:-1])) - 1000.0
    return score

